cat > src/routes/contact.kay <<'EOF'
--- server
import { t } from 'kay'
import { validateContact } from '../contact'

export const send = action(t.Object({ name: t.String(), email: t.String(), message: t.String() }), (fields, ctx) => {
  const errors = validateContact(fields)

  if (Object.keys(errors).length > 0)
    return ctx.fail(422, { errors })

  return { name: fields.name.trim() }
})
