ContactForm
EOF
cat > src/components/contact-form.kay <<'EOF'
---
import { ActionError } from 'kay'
import { send } from '../routes/contact.kay'
import { validateContact } from '../contact'
import type { ContactErrors } from '../contact'

const clientErrors = signal<ContactErrors | null>(null)
const sentName = signal<string | null>(null)
const errors = (): ContactErrors => clientErrors() ?? send.failed()?.data.errors ?? {}
const thanks = () => sentName() ?? send.succeeded()?.data.name ?? null

async function submit(event: SubmitEvent) {
  event.preventDefault()

  const form = event.currentTarget as HTMLFormElement
  const data = new FormData(form)
  const found = validateContact({
    name: String(data.get('name')),
    email: String(data.get('email')),
    message: String(data.get('message')),
  })

  clientErrors.set(found)
  sentName.set(null)

  if (Object.keys(found).length > 0)
    return

  try {
    const result = await send(data, { refresh: false })

    sentName.set(result.name)
    form.reset()
  }
  catch (error) {
    if (error instanceof ActionError)
      clientErrors.set((error.data as { errors?: ContactErrors } | undefined)?.errors ?? {})
    else
      throw error
  }
}
---
if thanks()
  p(role="status") Thanks, {thanks()}! Your message has been sent.
form.flex.max-w-lg.flex-col.gap-4(action={send} novalidate onSubmit={submit})
  .flex.flex-col.gap-1
    label(for="contact-name") Name
    input#contact-name(type="text" name="name")
    if errors().name as message
      p.text-red {message}
  .flex.flex-col.gap-1
    label(for="contact-email") Email
    input#contact-email(type="email" name="email")
    if errors().email as message
      p.text-red {message}
  .flex.flex-col.gap-1
    label(for="contact-message") Message
    textarea#contact-message(name="message" rows="6")
    if errors().message as message
      p.text-red {message}
  button(type="submit") Send
EOF
